class NotifRow(AttrDict):
    "One notification thread as an actionable line"
    def __repr__(self):
        s = self.subject
        num = s.url.rpartition('/')[2] if s.url else ''
        kind = ('PR' if s.type=='PullRequest' else s.type) + (f' #{num}' if num.isdigit() else '')
        return f'{self.id}  {_age(self.updated_at)}  {self.reason}  {self.repository.full_name}  {self.get("mark","")}{kind}: {s.title}'

class NotifRows(GhRows):
    "Notification rows; displays 'no notifications' when empty"
    def __repr__(self): return super().__repr__() or 'no notifications'

def _notif_mark(sub):
    "`[merged] `/`[closed] ` marker for a fetched subject; empty for open or unfetchable subjects"
    if not sub: return ''
    if sub.get('merged_at'): return '[merged] '
    if sub.get('state') == 'closed': return '[closed] '
    return ''

async def gh_notifs(days=5, reasons=('mention', 'review_requested', 'author', 'assign'), include_read=False, per_page=100):
    "Notifications from the past `days` (all available if None) as `NotifRows`, marked `[closed]`/`[merged]` when the subject is no longer open; `reasons=None` includes every reason"
    api = GhApi()
    since = (datetime.now(timezone.utc) - timedelta(days=days)).isoformat() if days else None
    notifs = L([o async for o in paged(api.activity.list_notifications_for_authenticated_user, all=include_read, since=since, per_page=per_page)]).concat()
    if reasons: notifs = notifs.filter(lambda n: n.reason in reasons)
    async def _get(u):
        if not u: return None
        try: return await api(u, 'GET')
        except APIError: return None   # deleted or inaccessible subjects lose their mark, not the whole listing
    subs = await asyncio.gather(*(_get(n.subject.url) for n in notifs))
    for n, s in zip(notifs, subs): n['mark'] = _notif_mark(s)
    return NotifRows(NotifRow(o) for o in notifs)

